// ─────────────────────────────────────────────────────────────────────────
// IMPORT ERROR BOUNDARY — catches render-phase errors in import preview
// ─────────────────────────────────────────────────────────────────────────
class ImportErrorBoundary extends React.Component {
  constructor(props) { super(props); this.state = { err: null }; }
  static getDerivedStateFromError(e) { return { err: e }; }
  render() {
    if (this.state.err) {
      return React.createElement('div', {
        style: { color:'#991b1b', fontSize:12, padding:'10px 12px', background:'#fee2e2',
                 borderRadius:8, border:'1px solid #dc2626', marginTop:8 }
      },
        'Import preview error — ', this.state.err.message || 'unexpected error.',
        React.createElement('button', {
          style: { display:'block', marginTop:6, color:'#6e6a66', fontSize:11,
                   background:'none', border:'none', cursor:'pointer', textDecoration:'underline' },
          onClick: () => this.setState({ err: null })
        }, 'Dismiss')
      );
    }
    return this.props.children;
  }
}

