// ═════════════════════════════════════════════════════════════════════════
// IEL MODULE v2 — mirrors RCD structure exactly
// Sites → Areas → Category view → Items (machines)
// ═════════════════════════════════════════════════════════════════════════

// Storage keys
const K_IEL_PROJECTS  = "iel-projects-v2";
const K_IEL_RESULTS   = "iel-results-v2";   // { siteId: { areaId: { cat: { itemId: {status,checks,notes,...} } } } }
const K_IEL_META      = "iel-meta-v2";
const K_IEL_CAT       = "iel-cat-v2";        // active category: "estops"|"lanyards"|"isolators"|null
const K_IEL_HISTORY   = "iel-history-v2";
const K_IEL_DROPDOWNS = "iel-dropdowns-v1";
const IEL_DEFAULT_RESPONSIBILITY = ["Site Electrician","Site Manager","Contractor","Client"];
const IEL_DEFAULT_RECTIFIED      = ["Removed from Service","Scheduled for Repair","Replacement Required","Under Investigation","No Action Required"];

const IEL_CATEGORIES = [
  { key:"estops",    label:"E-Stops",   icon:React.createElement('svg',{viewBox:'0 0 24 24',width:15,height:15,fill:'#dc2626',stroke:'none'},React.createElement('circle',{cx:12,cy:12,r:10})), color:"#dc2626", desc:"Emergency stop buttons & devices" },
  { key:"lanyards",  label:"Lanyards",  icon:React.createElement('svg',{viewBox:'0 0 24 24',width:15,height:15,fill:'none',stroke:'currentColor',strokeWidth:2,strokeLinecap:'round'},React.createElement('path',{d:'M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71'}),React.createElement('path',{d:'M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71'})), color:"#047857", desc:"Safety lanyards & fall arrest equipment" },
  { key:"isolators", label:"Isolators", icon:React.createElement('svg',{viewBox:'0 0 24 24',width:15,height:15,fill:'#a3530f',stroke:'none'},React.createElement('path',{d:'M13 2L4.5 13.5H11L10 22L19.5 10.5H13Z'})), color:"#92400e", desc:"Electrical isolators & lockout points" },
];
const IEL_TYPE_LABEL  = { estops:"Estop", lanyards:"Lanyard", isolators:"Isolator" };
const IEL_STATUS = { UNTESTED:"untested", PASS:"pass", FAIL:"fail", NA:"na" };
const IEL_SM = {
  untested: { label:"—",    bg:"#e4e4e7", fg:"#6e6a66",    border:"#d4d4d8" },
  pass:     { label:"PASS", bg:"#dcfce7", fg:"#14532d", border:"#16a34a" },
  fail:     { label:"FAIL", bg:"#fee2e2", fg:"#991b1b", border:"#dc2626" },
  na:       { label:"N/A",  bg:"#f1f5f9", fg:"#334155", border:"#94a3b8" },
};

function ielUid()  { return Math.random().toString(36).slice(2,9); }
function ielSlug(s){ return s.toLowerCase().replace(/[^a-z0-9]/g,"-").replace(/-+/g,"-").slice(0,20)+"-"+ielUid(); }
function isOverdue(d){ if(!d)return false; try{return new Date(d)<new Date();}catch(_){return false;} }
function isDueSoon(d){ if(!d)return false; try{const n=new Date(),tw=new Date(n.getTime()+14*864e5);const x=new Date(d);return x>=n&&x<=tw;}catch(_){return false;} }
function parseAUDate(val){
  if(!val)return"";const s=String(val).trim();
  const m=s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if(m)return`${m[3]}-${m[2].padStart(2,"0")}-${m[1].padStart(2,"0")}`;
  if(/^\d+(\.\d+)?$/.test(s)){try{const d=new Date(Math.round((parseFloat(s)-25569)*86400*1000));if(!isNaN(d))return d.toISOString().slice(0,10);}catch(_){}}
  try{const d=new Date(s);if(!isNaN(d))return d.toISOString().slice(0,10);}catch(_){}
  return s;
}
function ielTypeToKey(t){
  if(!t)return null;const s=String(t).trim().toLowerCase();
  if(s.includes("lanyard"))return"lanyards";
  if(s.includes("estop")||s.includes("e-stop")||s.includes("e stop"))return"estops";
  if(s.includes("isolat"))return"isolators";
  return null;
}

// ─── IEL data helpers ────────────────────────────────────────────────────
function ielGetItem(results,siteId,areaId,cat,itemId){
  return((((results[siteId]||{})[areaId]||{})[cat]||{})[itemId])||{status:IEL_STATUS.UNTESTED,mechCheck:false,circuitIso:false,lanyardCond:false,notes:"",priority:"",rectified:"",lastTested:""};
}
function ielGetStatus(results,siteId,areaId,cat,itemId){
  return(ielGetItem(results,siteId,areaId,cat,itemId).status)||IEL_STATUS.UNTESTED;
}
function ielCatSummary(results,siteId,areaId,cat,items){
  let pass=0,fail=0,na=0,untested=0;
  items.forEach(id=>{const v=ielGetStatus(results,siteId,areaId,cat,id);if(v===IEL_STATUS.PASS)pass++;else if(v===IEL_STATUS.FAIL)fail++;else if(v===IEL_STATUS.NA)na++;else untested++;});
  return{pass,fail,na,untested};
}
function ielSiteSummary(results,project,cat){
  let pass=0,fail=0,na=0,untested=0;
  project.areas.forEach(a=>{
    // only look at the panel whose name matches cat
    const catPanel=a.panels.find(p=>p.name===cat);
    if(!catPanel)return;
    catPanel.circuits.forEach(id=>{
      const v=ielGetStatus(results,project.id,a.id,cat,id);
      if(v===IEL_STATUS.PASS)pass++;else if(v===IEL_STATUS.FAIL)fail++;else if(v===IEL_STATUS.NA)na++;else untested++;
    });
  });
  return{pass,fail,na,untested,total:pass+fail+na+untested};
}

// ─── IEL Excel helpers ────────────────────────────────────────────────────
const IEL_C={green:"FF10B981",white:"FFFFFFFF",darkGrey:"FF2D2D2D",lightGrey:"FFF5F5F5",midGrey:"FFD9D9D9",passWhite:"FFFFFFFF",failRed:"FFFFC7CE",naGrey:"FFF2F2F2",priorityU_bg:"FF9B0000",priorityU_font:"FFFFFFFF",priorityH_bg:"FFFFC7CE",priorityH_font:"FF9C0006",priorityM_bg:"FFFFD966",priorityM_font:"FF7F6000",priorityL_bg:"FFE2EFDA",priorityL_font:"FF375623"};
function ielBorder(s="thin",c=IEL_C.midGrey){return{style:s,color:{rgb:c}};}
function ielAllBorders(){const b=ielBorder();return{top:b,bottom:b,left:b,right:b};}
function ielBtm(){return{bottom:ielBorder("hair")};}
function ielCS(fill,font={},align={},borders={}){return{fill:{patternType:"solid",fgColor:{rgb:fill}},font:{name:"Calibri",sz:10,...font},alignment:{vertical:"center",...align},border:borders};}
function ielPriColor(p){if(p==="U")return{bg:IEL_C.priorityU_bg,font:IEL_C.priorityU_font,bold:true};if(p==="H")return{bg:IEL_C.priorityH_bg,font:IEL_C.priorityH_font,bold:false};if(p==="M")return{bg:IEL_C.priorityM_bg,font:IEL_C.priorityM_font,bold:false};if(p==="L")return{bg:IEL_C.priorityL_bg,font:IEL_C.priorityL_font,bold:false};return null;}
function ielDS(ri,pf,priority=""){if(priority){const pc=ielPriColor(priority);if(pc)return ielCS(pc.bg,{sz:9,color:{rgb:pc.font},bold:pc.bold},{wrapText:true},ielBtm());}let bg=ri%2===0?IEL_C.white:IEL_C.lightGrey,fontColor=IEL_C.darkGrey,bold=false;if(pf==="Pass")bg=IEL_C.passWhite;if(pf==="Fail"){bg=IEL_C.failRed;fontColor=IEL_C.priorityH_font;bold=true;}if(pf==="N/A")bg=IEL_C.naGrey;return ielCS(bg,{sz:9,color:{rgb:fontColor},bold},{wrapText:true},ielBtm());}
function ielSetCell(ws,ref,value,style){const t=typeof value==="number"?"n":"s";ws[ref]={v:value!=null?value:"",t,s:style};}

function exportIELExcel(project, results, meta) {
  const wb=XLSX.utils.book_new();
  const testDate=(meta&&meta.testDate)||"";
  const auditor=(meta&&meta.auditor)||"";
  const nextDue=meta&&meta.nextTestDate?fmtDate(meta.nextTestDate):addMonths(testDate,3);
  const sName=project.name||"Site";
  const headers=["Location","Type","Machine","Date","Mechanism / Reset Check","Circuit Isolation Verified","Lanyard Tension / Cond.","Pass / Fail","Rectified / Scheduled","Date Rectified / Scheduled","Defect ID","Responsibility","Notes / Recommendations","Priority (L,M,H,U)","Next Test Due (3 months)"];
  const n=headers.length;
  const cols="ABCDEFGHIJKLMNO".slice(0,n).split("");
  const titleSt=ielCS("FF2D2D2D",{bold:true,sz:14,color:{rgb:"FFFFFFFF"}},{horizontal:"left"});
  const subSt=ielCS("FF1E1E1E",{sz:9,color:{rgb:"FFbbbbbb"}},{horizontal:"left"});
  const metaSt=ielCS("FF262626",{sz:9,color:{rgb:"FF999999"}},{horizontal:"left"});
  const spaceSt=ielCS("FF1E1E1E");
  const hdrSt=ielCS(IEL_C.green,{bold:true,sz:10,color:{rgb:"FFFFFFFF"}},{horizontal:"center",wrapText:true},ielAllBorders());
  const rows=[];
  rows.push([`${sName} — Isolators, E-Stops & Lanyards Test`,...Array(n-1).fill("")]);
  rows.push([[project.company||'SparkCheck', project.abn?`ABN: ${project.abn}`:'', project.licence?`Electrical Licence: ${project.licence}`:''].filter(Boolean).join('  |  '),...Array(n-1).fill('')]);
  rows.push([`Auditor: ${auditor}`,"",`Date Tested: ${fmtDate(testDate)}`,"",`Next Test Due: ${nextDue}`,...Array(Math.max(0,n-5)).fill("")]);
  rows.push(Array(n).fill(""));
  rows.push(headers);
  const dataRows=[];
  const catOrder=["estops","lanyards","isolators"];
  // Organised by AREA first, then category within each area — no separator rows
  project.areas.forEach(area=>{
    catOrder.forEach(catKey=>{
      const catLabel=IEL_TYPE_LABEL[catKey]||catKey;
      const catPanel=area.panels.find(p=>p.name===catKey);
      if(!catPanel||!catPanel.circuits.length)return;
      catPanel.circuits.forEach(itemId=>{
        const machineName=(catPanel.machineNames||{})[itemId]||itemId;
        const item=defectGateByStatus((((results[area.id]||{})[catKey])||{})[itemId]||{status:IEL_STATUS.UNTESTED,mechCheck:false,circuitIso:false,lanyardCond:false,notes:"",priority:"",rectified:"",lastTested:""});
        const st=item.status||IEL_STATUS.UNTESTED;
        const pf=st===IEL_STATUS.PASS?"Pass":st===IEL_STATUS.FAIL?"Fail":st===IEL_STATUS.NA?"N/A":"Untested";
        const dueDate=item.lastTested?addMonths(item.lastTested,3):"";
        rows.push([
          area.name,catLabel,machineName,
          fmtDate(item.lastTested),
          item.mechCheck?"yes":"",
          item.circuitIso?"yes":"",
          catKey==="lanyards"?(item.lanyardCond?"yes":""):"",
          pf,
          item.rectified||"",item.scheduledDate?fmtDate(item.scheduledDate):"",
          item.defectId||"",item.responsibility||"",item.notes||"",item.priority||"",
          dueDate
        ]);
        dataRows.push({pf,priority:item.priority||""});
      });
    });
  });
  rows.push(Array(n).fill(""));
  rows.push([`Notes: ${(meta&&meta.notes)||""}`,...Array(n-1).fill("")]);
  const ws=XLSX.utils.aoa_to_sheet(rows);
  ws["!cols"]=[{wch:22},{wch:10},{wch:28},{wch:11},{wch:18},{wch:18},{wch:18},{wch:10},{wch:20},{wch:14},{wch:10},{wch:16},{wch:36},{wch:10},{wch:16}];
  ws["!rows"]=[{hpt:32},{hpt:16},{hpt:16},{hpt:6},{hpt:40}];
  ws["!merges"]=[{s:{r:0,c:0},e:{r:0,c:n-1}},{s:{r:1,c:0},e:{r:1,c:n-1}},{s:{r:2,c:0},e:{r:2,c:1}},{s:{r:2,c:2},e:{r:2,c:3}},{s:{r:2,c:4},e:{r:2,c:n-1}},{s:{r:3,c:0},e:{r:3,c:n-1}}];
  cols.forEach(col=>{ielSetCell(ws,`${col}1`,(ws[`${col}1`]||{}).v||"",titleSt);ielSetCell(ws,`${col}2`,(ws[`${col}2`]||{}).v||"",subSt);ielSetCell(ws,`${col}3`,(ws[`${col}3`]||{}).v||"",metaSt);ielSetCell(ws,`${col}4`,"",spaceSt);ielSetCell(ws,`${col}5`,(ws[`${col}5`]||{}).v||"",hdrSt);});
  let row=6;dataRows.forEach((dr,ri)=>{
    cols.forEach(col=>{const ref=`${col}${row}`;ielSetCell(ws,ref,(ws[ref]||{}).v||"",ielDS(ri,dr.pf,dr.priority));});
    row++;
  });
  XLSX.utils.book_append_sheet(wb,ws,"Isolators EStops Lanyards");
  const filename=`IEL_${sName.replace(/\s+/g,"_")}_${testDate||"export"}.xlsx`;
  const wbOut=XLSX.write(wb,{bookType:"xlsx",type:"base64",cellStyles:true,bookSST:false});
  deliverExportFile(wbOut, filename);
}

// Import — same format as export
function parseIELExcel(data){
  const ws=data.Sheets[data.SheetNames[0]];
  const rows=XLSX.utils.sheet_to_json(ws,{header:1,defval:""});
  let headerIdx=-1;
  for(let i=0;i<Math.min(rows.length,10);i++){
    if(rows[i].some(c=>String(c).length>60)) continue;
    const r=rows[i].map(c=>String(c).toLowerCase());
    if(r.some(c=>c==="location"||c==="area")&&r.some(c=>c==="type")){headerIdx=i;break;}
  }
  if(headerIdx===-1)headerIdx=4;
  const header=rows[headerIdx].map(c=>String(c).toLowerCase().trim());
  const col=search=>header.findIndex(h=>h.includes(search));
  const cLoc=col("location"),cType=col("type"),cMachine=col("machine"),cDate=col("date");
  const cMech=header.findIndex(h=>h.includes("mechanism")||h.includes("reset"));
  const cCirc=header.findIndex(h=>h.includes("circuit")&&h.includes("iso"));
  const cLany=header.findIndex(h=>h.includes("lanyard")&&(h.includes("tension")||h.includes("cond")));
  const cPF=header.findIndex(h=>h.includes("pass")||h.includes("fail"));
  const cRect=header.findIndex(h=>h.includes("rectif")||h.includes("schedul"));
  const cDRect=header.findIndex((h,i)=>i>cRect&&(h.includes("date")||h.includes("schedul")));
  const cDef=col("defect"),cResp=col("responsib"),cNotes=header.findIndex(h=>h.includes("note")||h.includes("recommend")),cPri=col("priority");
  let siteName="",parsedCompany="",parsedAbn="",parsedLicence="";
  if(rows[0]&&rows[0][0]){const t=String(rows[0][0]);siteName=t.split(/\s*[-–]\s*/)[0].trim()||t;}
  // Company/ABN/licence live in row 2 (index 1), not the title row
  if(rows[1]&&rows[1][0]){
    const p=parseCompanyRow(rows[1][0]);
    // Only use as company if it doesn't look like a site/test title (no dates, no "test")
    const raw=String(rows[1][0]).toLowerCase();
    const looksLikeTitle=raw.includes(" test")||raw.includes("march")||raw.includes("april")||raw.includes("january")||raw.includes("february")||/\d{4}/.test(raw)&&!raw.includes("abn");
    if(!looksLikeTitle){parsedCompany=p.company||"";}
    parsedAbn=p.abn||"";
    parsedLicence=p.licence||"";
  }
  // Build areas from Location column, panels from area+type grouping, items = machines
  const areaMap={};
  for(let i=headerIdx+1;i<rows.length;i++){
    const row=rows[i];
    const typeRaw=cType>=0?String(row[cType]||"").trim():"";
    const catKey=ielTypeToKey(typeRaw);
    if(!catKey)continue;
    const location=cLoc>=0?String(row[cLoc]||"").trim():"General";
    const machine=cMachine>=0?String(row[cMachine]||"").trim():"";
    if(!machine)continue;
    if(!areaMap[location])areaMap[location]={};
    if(!areaMap[location][catKey])areaMap[location][catKey]=[];
    const itemId=ielUid();
    // Import structure only — all results start blank for a fresh audit
    areaMap[location][catKey].push({
      itemId,machine,
      data:{
        status:IEL_STATUS.UNTESTED,
        lastTested:"",
        mechCheck:false,
        circuitIso:false,
        lanyardCond:false,
        rectified:"",
        scheduledDate:"",
        defectId:"",
        responsibility:"",
        notes:"",
        priority:"",
      }
    });
  }
  // Build project structure: areas, panels (one per catKey), circuits (itemIds)
  // results: { [siteId]: { [areaId]: { [catKey]: { [itemId]: data } } } }
  const areas=Object.entries(areaMap).map(([aName,catMap])=>({
    id:ielSlug(aName),name:aName,
    panels:Object.entries(catMap).map(([catKey,itemArr])=>({
      id:ielSlug(catKey+"-"+aName),name:catKey,
      circuits:itemArr.map(i=>i.itemId),
      // store machine names on panel for display
      machineNames:Object.fromEntries(itemArr.map(i=>[i.itemId,i.machine])),
    }))
  }));
  // Flatten results
  const results={};
  const siteId=ielSlug(siteName||"site");
  results[siteId]={};
  Object.entries(areaMap).forEach(([aName,catMap])=>{
    const areaId=areas.find(a=>a.name===aName).id;
    results[siteId][areaId]={};
    Object.entries(catMap).forEach(([catKey,itemArr])=>{
      results[siteId][areaId][catKey]={};
      itemArr.forEach(({itemId,data})=>{results[siteId][areaId][catKey][itemId]=data;});
    });
  });
  return{siteName,siteId,areas,results,company:parsedCompany,abn:parsedAbn,licence:parsedLicence};
}

function downloadIELTemplate(){
  const XLSX=XLSX_LIB; if(!XLSX){alert("Excel library not loaded");return;}
  const wb=XLSX.utils.book_new();
  const rows=[
    ["Site Name — enter your site name here"],
    ["Company Name  |  ABN: 12 345 678 901  |  Electrical Licence: 123456C"],
    [""],
    ["INSTRUCTIONS: Fill in Location (area), Type (Estop / Lanyard / Isolator) and Machine name. One item per row. Type must be exactly: Estop, Lanyard, or Isolator. Rows 1-3 are read automatically."],
    ["Location","Type","Machine / Asset Name"],
    ["Wash Plant","Estop","Conveyor Feed Belt E/S"],
    ["Wash Plant","Estop","Screen Deck E/S"],
    ["Wash Plant","Lanyard","Crusher Feed Conveyor — Lanyard"],
    ["Wash Plant","Lanyard","Screen Deck Access — Lanyard"],
    ["Wash Plant","Isolator","Crusher Feed Isolator"],
    ["Sub Station","Estop","Pump Station E/S"],
    ["Sub Station","Isolator","Pump Station Isolator"],
    ["Workshop","Estop","Lathe E/S"],
    ["Workshop","Lanyard","Overhead Crane — Lanyard"],
  ];
  const ws=XLSX.utils.aoa_to_sheet(rows);
  ws["!cols"]=[{wch:26},{wch:12},{wch:36}];
  const colHdrFill={patternType:"solid",fgColor:{rgb:"FF2D2D2D"}};
  const colHdrFont={name:"Calibri",bold:true,sz:10,color:{rgb:"FFeeeeee"}};
  const infoFill={patternType:"solid",fgColor:{rgb:"FF1E3A5F"}};
  const infoFont={name:"Calibri",sz:9,color:{rgb:"FFadd8e6"},italic:true};
  ["A1"].forEach(r=>{if(ws[r])ws[r].s={fill:{patternType:"solid",fgColor:{rgb:"FF1a1a1a"}},font:{name:"Calibri",bold:true,sz:13,color:{rgb:"FF10b981"}}};});
  ["A2"].forEach(r=>{if(ws[r])ws[r].s={fill:{patternType:"solid",fgColor:{rgb:"FF1a1a1a"}},font:{name:"Calibri",sz:10,color:{rgb:"FF999999"}}};});
  ["A4"].forEach(r=>{if(ws[r])ws[r].s={fill:infoFill,font:infoFont};});
  ["A5","B5","C5"].forEach(r=>{if(ws[r])ws[r].s={fill:colHdrFill,font:colHdrFont,alignment:{horizontal:"center"}};});
  ws["!merges"]=[{s:{r:0,c:0},e:{r:0,c:2}},{s:{r:1,c:0},e:{r:1,c:2}},{s:{r:3,c:0},e:{r:3,c:2}}];
  XLSX.utils.book_append_sheet(wb,ws,"IEL Import");
  const tOut=XLSX.write(wb,{bookType:"xlsx",type:"base64",cellStyles:true});
  const fname="IEL_Import_Template.xlsx";
  deliverExportFile(tOut, fname);
}

// ═════════════════════════════════════════════════════════════════════════
// IEL APP — mirrors RCD app structure exactly
// ═════════════════════════════════════════════════════════════════════════
function IELApp({ onGoHome }) {
  const [projects,      setProjects]     = React.useState([]);
  const [allResults,    setAllResults]   = React.useState({});
  const [allMeta,       setAllMeta]      = React.useState({});
  const [history,       setHistory]      = React.useState([]);
  const [loaded,        setLoaded]       = React.useState(false);
  const [saveFlash,     setSaveFlash]    = React.useState(false);
  const [activeProject, setActiveProject]= React.useState(null);
  const [activeCat,     setActiveCat]    = React.useState(null);
  const [auditEntered,  setAuditEntered] = React.useState(() => { try { return !!JSON.parse(localStorage.getItem(K_IEL_CAT)); } catch { return false; } }); // "estops"|"lanyards"|"isolators"
  const [view,          setView]         = React.useState("projects"); // projects|home|audit|panel|manage|history|report
  const [activeAreaId,  setActiveAreaId] = React.useState(null);
  const [activePanelId, setActivePanelId]= React.useState(null);
  const [detailInfo,    setDetailInfo]   = React.useState(null); // {areaId,panelId,itemId}
  const [ielDropdowns,  setIelDropdowns] = React.useState({responsibility:IEL_DEFAULT_RESPONSIBILITY,rectified:IEL_DEFAULT_RECTIFIED});
  const [viewSnap,      setViewSnap]     = React.useState(null);
  const [viewArea,      setViewArea]     = React.useState(null);
  const [viewCat,       setViewCat]      = React.useState(null);

  React.useEffect(()=>{
    var t=setTimeout(()=>setLoaded(true),3000);
    (async()=>{
      try{
        const[p,r,m,h,cat,dd]=await Promise.all([load(K_IEL_PROJECTS,[]),load(K_IEL_RESULTS,{}),load(K_IEL_META,{}),load(K_IEL_HISTORY,[]),load(K_IEL_CAT,null),load(K_IEL_DROPDOWNS,{responsibility:IEL_DEFAULT_RESPONSIBILITY,rectified:IEL_DEFAULT_RECTIFIED})]);
        setActiveCat(cat); setIelDropdowns(dd);
        clearTimeout(t);setProjects(p);setAllResults(r);setAllMeta(m);setHistory(h);setLoaded(true);
      }catch(e){clearTimeout(t);setLoaded(true);}
    })();
  },[]);

  React.useEffect(()=>{if(loaded)save(K_IEL_PROJECTS,projects);},[projects,loaded]);
  React.useEffect(()=>{if(loaded){save(K_IEL_RESULTS,allResults);setSaveFlash(true);const t=setTimeout(()=>setSaveFlash(false),1200);return()=>clearTimeout(t);}},[allResults,loaded]);
  React.useEffect(()=>{if(loaded)save(K_IEL_META,allMeta);},[allMeta,loaded]);
  React.useEffect(()=>{if(loaded)save(K_IEL_CAT,activeCat);},[activeCat,loaded]);
  React.useEffect(()=>{if(loaded)save(K_IEL_HISTORY,history);},[history,loaded]);
  React.useEffect(()=>{if(loaded)save(K_IEL_DROPDOWNS,ielDropdowns);},[ielDropdowns,loaded]);

  const mainElRef = React.useRef(null);
  const savedScrollRef = React.useRef(0);
  React.useEffect(()=>{
    if(!detailInfo&&mainElRef.current&&savedScrollRef.current>0){
      mainElRef.current.scrollTop=savedScrollRef.current;
    }
  },[detailInfo]);
  React.useLayoutEffect(()=>{
    if(detailInfo&&mainElRef.current) mainElRef.current.scrollTop=0;
  },[detailInfo]);

  const project  = projects.find(p=>p.id===activeProject);
  const _ielMeta = allMeta[activeProject]||{auditor:"",testDate:new Date().toISOString().slice(0,10),notes:""};
  const meta = {
    ..._ielMeta,
    nextTestDate: _ielMeta.nextTestDate || addMonthsISO(_ielMeta.testDate, 3),
  };
  const setMeta  = patch=>setAllMeta(prev=>({...prev,[activeProject]:{...meta,...patch}}));
  const area     = project&&project.areas.find(a=>a.id===activeAreaId);
  // panel here represents a category-panel (panel.name = catKey)
  const panel    = area&&area.panels.find(p=>p.id===activePanelId);
  const catInfo  = IEL_CATEGORIES.find(c=>c.key===activeCat)||IEL_CATEGORIES[0];

  const patchItem=(pid,aid,cat,itemId,patch)=>{
    setAllResults(prev=>{
      const old=((((prev[pid]||{})[aid]||{})[cat])||{})[itemId]||{};
      return{...prev,[pid]:{...prev[pid],[aid]:{...(prev[pid]||{})[aid],[cat]:{...((prev[pid]||{})[aid]||{})[cat],[itemId]:(patch.status===IEL_STATUS.FAIL?failFill({...old,...patch},(ielDropdowns||{}).rectified,(ielDropdowns||{}).responsibility):{...old,...patch})}}}};
    });
  };

  const archiveAudit=()=>{
    if(!project)return;
    const catLabel=activeCat?(IEL_CATEGORIES.find(c=>c.key===activeCat)||{label:activeCat}).label:"All Categories";
    const snap={id:ielUid(),projectId:activeProject,projectName:project.name,auditor:meta.auditor||"",testDate:meta.testDate||"",cat:activeCat||null,label:catLabel,archivedAt:new Date().toISOString(),results:JSON.parse(JSON.stringify(allResults[activeProject]||{})),meta:{...meta}};
    setHistory(prev=>[snap,...prev].slice(0,100));
    return snap;
  };

  const goProjects=()=>{setView("projects");setActiveProject(null);setActiveCat(null);setActiveAreaId(null);setActivePanelId(null);setAuditEntered(false);};
  const goHome=()=>{setView("home");setActiveAreaId(null);setActivePanelId(null);};

  if(!loaded)return React.createElement('div',{style:SI.loader},React.createElement('div',{style:SI.loaderSpinner}),React.createElement('p',{style:{color:"#6e6a66",marginTop:16}},"Loading…"));

  const catColor = catInfo?catInfo.color:"#047857";
  const isAudit  = view==="audit"||view==="panel";
  const summary  = project&&activeCat?ielSiteSummary(allResults,project,activeCat):{total:0,pass:0,fail:0,na:0,untested:0};
  const canGoBack= view!=="projects";

  const handleBack=()=>{
    if(viewSnap&&viewArea){setViewArea(null);return;}
    if(viewSnap){setViewSnap(null);setViewArea(null);setViewCat(null);return;}
    if(detailInfo){setDetailInfo(null);return;}
    if(view==="dropdowns"){setView("home");return;}
    if(view==="panel"){setView("audit");setActivePanelId(null);}
    else if(view==="audit"&&activePanelId){setActivePanelId(null);}
    else if(view==="audit"&&activeAreaId){setActiveAreaId(null);}
    else if(view==="audit"&&auditEntered&&!activeAreaId){const hasProgress=project?IEL_CATEGORIES.some(c=>{const s=ielSiteSummary(allResults,project,c.key);return s.total>0&&(s.pass+s.fail+s.na)>0;}):false;setAuditEntered(hasProgress);setView("home");}
    else if(view==="audit"&&!activeAreaId){setView("home");}
    else if(view==="home"){goProjects();}
    else if(["manage","report","history","dropdowns"].includes(view)){setView("home");}
    else goProjects();
  };

  return React.createElement('div',{style:SI.root}
    // ── Header
    ,React.createElement('div',{style:{padding:'48px 18px 12px',borderBottom:'1px solid #f0eeea',background:'#f0eeea',flexShrink:0}}
      ,React.createElement('div',{style:{display:'flex',justifyContent:'space-between',alignItems:'flex-start',gap:12}}
        ,React.createElement('div',{style:{flex:1,minWidth:0,display:'flex',flexDirection:'column',gap:4}}
          ,view !== "projects" && React.createElement('div',{style:{border:'1px solid rgba(0,0,0,0.06)',borderRadius:'10px',padding:'8px 12px',background:'#f0eeea',flexShrink:0,alignSelf:'flex-start',marginBottom:10,display:'flex',alignItems:'center',gap:6,cursor:'pointer'},onClick:handleBack}
            ,React.createElement('svg',{width:10,height:10,viewBox:"0 0 24 24",fill:"none",stroke:"#52525b",strokeWidth:2.5,strokeLinecap:"round"},React.createElement('polyline',{points:"15 18 9 12 15 6"}))
            ,React.createElement('span',{style:{fontSize:11,fontWeight:600,color:'#52525b'}},"Back")
          )
          ,React.createElement('div',{style:{fontFamily:"'Barlow Condensed',sans-serif",fontSize:22,fontWeight:600,letterSpacing:0.5,color:'#18181b',lineHeight:1.1,marginTop:6}},"IEL Testing")
          ,React.createElement('div',{style:{fontSize:12,color:'#52525b',marginTop:2,whiteSpace:'nowrap',overflow:'hidden',textOverflow:'ellipsis'}},project?.name||"")
        )
        ,React.createElement('div',{style:{border:'1px solid rgba(0,0,0,0.06)',borderRadius:'10px',padding:'8px 12px',background:'#f0eeea',flexShrink:0,marginTop:2,display:'flex',alignItems:'center',gap:6,cursor:'pointer'},onClick:onGoHome}
          ,React.createElement('svg',{width:14,height:14,viewBox:"0 0 24 24",fill:"none",stroke:"#52525b",strokeWidth:1.8,strokeLinecap:"round",strokeLinejoin:"round"},React.createElement('rect',{x:3,y:3,width:7,height:7,rx:1}),React.createElement('rect',{x:14,y:3,width:7,height:7,rx:1}),React.createElement('rect',{x:3,y:14,width:7,height:7,rx:1}),React.createElement('rect',{x:14,y:14,width:7,height:7,rx:1}))
          ,React.createElement('span',{style:{fontSize:11,fontWeight:600,color:'#52525b'}},"Modules")
        )
      )
      ,React.createElement('div',{style:{height:2,marginTop:12,background:'linear-gradient(90deg, #047857, transparent 70%)',opacity:0.5}})
    )

    // ── Main
    ,React.createElement('main',{style:SI.main,ref:mainElRef}
      ,view==="projects"&&React.createElement(IELProjectListView,{projects,allResults,onSelect:id=>{const proj=projects.find(p=>p.id===id);const hasProgress=IEL_CATEGORIES.some(cat=>{const s=ielSiteSummary(allResults,proj,cat.key);return s.total>0&&(s.pass+s.fail+s.na)>0;});setAuditEntered(hasProgress);setActiveProject(id);setView("home");},onAddProject:(p,importedResults)=>{setProjects(prev=>[...prev,p]);if(importedResults)setAllResults(prev=>({...prev,[p.id]:importedResults}));},onDeleteProject:id=>{setProjects(prev=>prev.filter(p=>p.id!==id));setAllResults(prev=>{const n={...prev};delete n[id];return n;});if(activeProject===id)goProjects();}})
      ,view==="home"&&project&&React.createElement(IELProjectHomeView,{project,meta,setMeta,results:allResults,onStartCat:cat=>{setActiveCat(cat);setView("audit");setAuditEntered(true);},onReport:()=>setView("report"),onManage:()=>setView("manage"),onHistory:()=>setView("history"),onReset:()=>{setAllResults(prev=>({...prev,[activeProject]:{}}));setAllMeta(prev=>({...prev,[activeProject]:{...prev[activeProject],testDate:new Date().toISOString().slice(0,10),nextTestDate:""}}));},onExport:()=>exportIELExcel(project,allResults[activeProject]||{},meta),activeCatKey:activeCat,auditEntered,lastArchivedAt:history.filter(h=>h.projectId===activeProject).reduce((latest,h)=>!latest||h.archivedAt>latest?h.archivedAt:latest,null),onCompleteAudit:()=>{archiveAudit();setAllResults(prev=>{const proj=prev[activeProject]||{};const cleared={};Object.keys(proj).forEach(aid=>{cleared[aid]={};IEL_CATEGORIES.forEach(c=>{cleared[aid][c.key]={};});});return{...prev,[activeProject]:cleared};});setAllMeta(prev=>({...prev,[activeProject]:{...prev[activeProject],testDate:new Date().toISOString().slice(0,10),notes:""}}));setActiveCat(null);setAuditEntered(false);setActiveAreaId(null);setActivePanelId(null);}})
      ,isAudit&&project&&!auditEntered&&React.createElement(AuditGatePage,{color:activeCat?catColor:"#047857",moduleLabel:"IEL TEST",auditLabel:activeCat?(IEL_CATEGORIES.find(c=>c.key===activeCat)||{label:activeCat}).label:"",hasActiveAudit:!!activeCat,onGoHome:goHome,onEnterAudit:()=>setAuditEntered(true),isRCD:false})
      ,isAudit&&project&&auditEntered&&!activeAreaId&&React.createElement(IELAreaListView,{project,results:allResults,cat:activeCat,catColor,onSelect:id=>setActiveAreaId(id)})
      ,isAudit&&project&&auditEntered&&activeAreaId&&area&&!activePanelId&&React.createElement(IELPanelListView,{area,project,results:allResults,cat:activeCat,catColor,onSelect:id=>{setActivePanelId(id);setView("panel");}})
      ,!detailInfo&&view==="panel"&&panel&&React.createElement(IELItemGrid,{area,panel,project,results:allResults,cat:activeCat,catColor,meta,onPatch:(itemId,patch)=>patchItem(activeProject,activeAreaId,activeCat,itemId,patch),onSetAll:(itemId,s)=>patchItem(activeProject,activeAreaId,activeCat,itemId,{status:s}),onOpenDetail:itemId=>{if(mainElRef.current)savedScrollRef.current=mainElRef.current.scrollTop;setDetailInfo({areaId:activeAreaId,panelId:activePanelId,itemId});}})
      ,detailInfo&&project&&React.createElement(IELItemModal,{...detailInfo,project,cat:activeCat,results:allResults,meta,dropdowns:ielDropdowns,onPatch:patch=>patchItem(activeProject,detailInfo.areaId,activeCat,detailInfo.itemId,patch),onClose:()=>setDetailInfo(null)})
      ,!detailInfo&&view==="report"&&project&&React.createElement(IELReportView,{project,results:allResults,meta,onBack:()=>setView("home")})
      ,!detailInfo&&view==="manage"&&project&&React.createElement(IELManageView,{project,onUpdateProject:updated=>setProjects(prev=>prev.map(p=>p.id===updated.id?updated:p)),onBack:()=>setView("home")})
      ,!detailInfo&&view==="dropdowns"&&React.createElement(IELDropdownsView,{dropdowns:ielDropdowns,setDropdowns:setIelDropdowns,onBack:()=>setView("home")})
      ,!detailInfo&&view==="history"&&React.createElement(IELHistoryView,{history:history.filter(h=>h.projectId===activeProject),project,viewSnap,setViewSnap,viewArea,setViewArea,viewCat,setViewCat,onDelete:id=>setHistory(prev=>prev.filter(h=>h.id!==id)),onExportSnap:snap=>exportIELExcel(project,snap.results||{},snap.meta||{}),
        onContinueFromSnap:(snap)=>{
          setAllResults(prev=>({...prev,[activeProject]:JSON.parse(JSON.stringify(snap.results||{}))}));
          setAllMeta(prev=>({...prev,[activeProject]:{...snap.meta}}));
          setActiveCat(null);
          setAuditEntered(false);
          setActiveAreaId(null);
          setActivePanelId(null);
          setView("home");
        },onBack:()=>setView("home")})
    )



    // ── Bottom nav
    ,view!=="projects"&&React.createElement('nav',{style:SI.bottomNav}
      ,React.createElement(IELNavBtn,{icon:NAV_ICON_HOME,     label:"Home",     active:view==="home",     color:"#334155",onClick:()=>{setDetailInfo(null);goHome();}})
      ,React.createElement(IELNavBtn,{icon:NAV_ICON_AUDIT,    label:"Audit",    active:isAudit,          color:"#334155",onClick:()=>{setDetailInfo(null);setView("audit");setActivePanelId(null);}})
      ,React.createElement(IELNavBtn,{icon:NAV_ICON_REPORT,   label:"Report",   active:view==="report",  color:"#334155",onClick:()=>{setDetailInfo(null);setView("report");}})
      ,React.createElement(IELNavBtn,{icon:NAV_ICON_HISTORY,  label:"History",  active:view==="history", color:"#334155",onClick:()=>{setDetailInfo(null);setView("history");}})
      ,React.createElement(IELNavBtn,{icon:NAV_ICON_MANAGE,   label:"Manage",   active:view==="manage",  color:"#334155",onClick:()=>{setDetailInfo(null);setView("manage");}})
      ,React.createElement(IELNavBtn,{icon:NAV_ICON_DROPDOWNS,label:"Dropdowns",active:view==="dropdowns",color:"#334155",onClick:()=>{setDetailInfo(null);setView("dropdowns");}})
    )
  );
}

