function calUid(){ return Math.random().toString(36).slice(2,9); }

function daysUntil(dateStr){
  if(!dateStr) return null;
  try{
    // Parse as local date by splitting manually — avoids UTC midnight vs local midnight off-by-one
    const [y,m,d] = dateStr.split("-").map(Number);
    const due = new Date(y, m-1, d);
    const now = new Date();
    now.setHours(0,0,0,0);
    due.setHours(0,0,0,0);
    return Math.round((due-now)/(1000*60*60*24));
  }catch(_){return null;}
}

function urgencyColor(days){
  if(days===null) return "#a1a1aa";
  if(days<0) return "#dc2626";
  if(days<=7) return "#dc2626";
  if(days<=14) return "#92400e";
  if(days<=30) return "#78350f";
  return "#16a34a";
}

function urgencyLabel(days){
  if(days===null) return "";
  if(days<0) return `OVERDUE ${Math.abs(days)}d`;
  if(days===0) return "DUE TODAY";
  if(days===1) return "DUE TOMORROW";
  if(days<=7) return `${days}d — THIS WEEK`;
  if(days<=14) return `${days}d — 2 WEEKS`;
  if(days<=30) return `${days}d`;
  return `${days}d`;
}

