  const resetKey   = (key, def) => setDropdowns(d=>({...d,[key]:def}));
  const setDefault = (key, val) => {
    const items = (dropdowns[key]||[]);
    setDropdowns(d=>({...d,[key]:[val,...items.filter(x=>x!==val)]}));
  };

